                        handleGetItems(request, response);
                    }
                    else if ("PLACE_BID".equals(action)) {
                        // CLIENT MUỐN ĐẤU GIÁ
                        handlePlaceBid(request, response);
                    }
                    else if ("GET_PENDING_ITEMS".equals(action)) {
                        // ADMIN XEM DANH SÁCH CHỜ DUYỆT
                        handleGetPendingItems(request, response);
                    }
                    else if ("APPROVE_ITEM".equals(action)) {
                        // ADMIN DUYỆT BIỂN SỐ
                        handleApproveItem(request, response);
                    }
                    else {
                        // ACTION KHÔNG NHẬN DẠng
                        response.put("status", "error");
                        response.put("message", "Action không hợp lệ: " + action);
                    }

                    // GỬI RESPONSE VỀ CLIENT
                    String jsonResponse = response.toString();
                    System.out.println("Gửi response: " + jsonResponse);
                    pw.println(jsonResponse);

                } catch (Exception e) {
                    //LỖI KHI PARSE JSON HOẶC XỬ LÝ
                    System.err.println("Lỗi xử lý: " + e.getMessage());

                    // GỬI ERROR RESPONSE VỀ CLIENT
                    JSONObject errorResponse = new JSONObject();
                    errorResponse.put("status", "error");
                    errorResponse.put("message", "Lỗi server: " + e.getMessage());
                    pw.println(errorResponse.toString());
                }
            }

            // KẾT THÚC KẾT NỐI
            System.out.println("Client ngắt kết nối: " + s.getRemoteSocketAddress());

        } catch (IOException e) {
            System.err.println("I/O error: " + e.getMessage());
        }
    }

    /**
     *HANDLE GET_ITEMS
     * Client yêu cầu: xem danh sách biển số đã duyệt
     */
    private void handleGetItems(JSONObject request, JSONObject response) {
        try {
            String type = request.optString("type", "Car");  // Mặc định là "Car"

            // LẤY DANH SÁCH TỬ DATABASE
            List<String[]> items = ProductService.getApprovedProductsByType(type);

            // CONVERT THÀNH JSON
            JSONArray itemsArray = new JSONArray();
            for (String[] item : items) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("start_price", item[2]);
                itemObj.put("current_price", item[3]);
                itemObj.put("description", item[4]);
                itemObj.put("vehicle_type", item[5]);
                itemsArray.put(itemObj);
            }

            // TẠO RESPONSE
            response.put("status", "success");
            response.put("items", itemsArray);
            response.put("count", items.size());

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE PLACE_BID
     * Client muốn đấu giá (tăng giá)
     */
    private void handlePlaceBid(JSONObject request, JSONObject response) {
        try {
            int itemId = request.getInt("itemId");
            int userId = request.getInt("userId");  // Lấy user ID từ client
            double amount = request.getDouble("amount");

            //  LƯU VÀO DATABASE
            BidDAO.addBid(itemId, userId, amount);

            // Cập nhật giá hiện tại của item
            ItemDAO.updateCurrentPrice(itemId, amount);

            // ✅ BROADCAST giá mới qua WebSocket tới tất cả clients đang theo dõi
            AuctionWebSocketServer wsServer = AuctionWebSocketServer.getInstance();
            User user = UserDAO.getUserById(userId);
            String bidderName = (user != null) ? user.getFullName() : "Người dùng #" + userId;
            wsServer.broadcastPriceUpdate(itemId, amount, userId, bidderName);

            response.put("status", "success");
            response.put("message", "Đấu giá thành công");
            response.put("new_price", amount);

            System.out.println("✅ PLACE_BID: itemId=" + itemId + ", newPrice=" + amount + " - Broadcast to WebSocket");

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
            System.err.println("❌ Lỗi PLACE_BID: " + e.getMessage());
        }
    }

    /**
     * HANDLE GET_PENDING_ITEMS (ADMIN)
     * Xem danh sách biển số chờ duyệt
     */
    private void handleGetPendingItems(JSONObject request, JSONObject response) {
        try {
            List<String[]> pendingItems = ProductService.getPendingProducts();

            JSONArray itemsArray = new JSONArray();
            for (String[] item : pendingItems) {
                JSONObject itemObj = new JSONObject();
                itemObj.put("id", item[0]);
                itemObj.put("plate_number", item[1]);
                itemObj.put("description", item[4]);
                itemObj.put("seller_name", item[7]);  // Tên người bán
                itemsArray.put(itemObj);
            }

            response.put("status", "success");
            response.put("pending_items", itemsArray);

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }

    /**
     * HANDLE APPROVE_ITEM (ADMIN)
     * Duyệt 1 biển số
     */
    private void handleApproveItem(JSONObject request, JSONObject response) {
        try {
            String plateNumber = request.getString("plate_number");

            boolean success = ProductService.approveProduct(plateNumber);

            if (success) {
                response.put("status", "success");
                response.put("message", "Duyệt biển số thành công");
            } else {
                response.put("status", "error");
                response.put("message", "Không thể duyệt biển số này");
            }

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", e.getMessage());
        }
    }
}

package com.auction.ui;

import org.java_websocket.client.WebSocketClient;
import org.java_websocket.handshake.ServerHandshake;
import org.json.JSONObject;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.List;

/**
 * WebSocket Client cho Auction System UI
 * Kết nối tới server WebSocket để nhận realtime updates
 */
public class AuctionWebSocketClient extends WebSocketClient {
    private static AuctionWebSocketClient instance;
    private final List<AuctionWebSocketListener> listeners = new CopyOnWriteArrayList<>();
    private boolean isConnected = false;

    public interface AuctionWebSocketListener {
        void onPriceUpdate(int itemId, double currentPrice, int bidderId, String bidderName);
        void onParticipantUpdate(int itemId, int participantCount);
        void onAuctionFinished(int itemId, double finalPrice, int winnerId, String winnerName);
        void onTimerExtended(int itemId, int newTimeRemaining);
        void onConnected();
        void onDisconnected();
    }

    private AuctionWebSocketClient(String serverUrl) throws URISyntaxException {
        super(new URI(serverUrl));
    }

    /**
     * Singleton - lấy hoặc tạo instance
     */
    public static synchronized AuctionWebSocketClient getInstance() {
        if (instance == null || !instance.isConnected) {
            try {
                instance = new AuctionWebSocketClient("ws://localhost:8081");
                instance.connect();
            } catch (URISyntaxException e) {
                e.printStackTrace();
            }
        }
        return instance;
    }

    @Override
    public void onOpen(ServerHandshake handshakedata) {
        System.out.println("✅ WebSocket UI Client kết nối thành công");
        isConnected = true;
        listeners.forEach(AuctionWebSocketListener::onConnected);
    }

    /**
     * Nhận message từ server
     */
    @Override
    public void onMessage(String message) {
        try {
            JSONObject json = new JSONObject(message);
            String type = json.optString("type", "");

            if ("PRICE_UPDATE".equals(type)) {
                int itemId = json.getInt("itemId");
                double currentPrice = json.getDouble("currentPrice");
                int bidderId = json.getInt("bidderId");
                String bidderName = json.getString("bidderName");

                listeners.forEach(listener -> listener.onPriceUpdate(itemId, currentPrice, bidderId, bidderName));

            } else if ("PARTICIPANT_UPDATE".equals(type)) {
                int itemId = json.getInt("itemId");
                int participantCount = json.getInt("participantCount");

                listeners.forEach(listener -> listener.onParticipantUpdate(itemId, participantCount));

            } else if ("AUCTION_FINISHED".equals(type)) {
                int itemId = json.getInt("itemId");
                double finalPrice = json.getDouble("finalPrice");
                int winnerId = json.getInt("winnerId");
                String winnerName = json.getString("winnerName");

                listeners.forEach(listener -> listener.onAuctionFinished(itemId, finalPrice, winnerId, winnerName));

            } else if ("TIMER_EXTENDED".equals(type)) {
                int itemId = json.getInt("itemId");
                int newTimeRemaining = json.getInt("newTimeRemaining");

                listeners.forEach(listener -> listener.onTimerExtended(itemId, newTimeRemaining));

            } else if ("SUBSCRIBED".equals(type)) {
                System.out.println(" Subscribed tới itemId: " + json.getInt("itemId"));
            }
        } catch (Exception e) {
            System.err.println("❌ Lỗi xử lý WebSocket message: " + e.getMessage());
        }
    }

    @Override
    public void onClose(int code, String reason, boolean remote) {
        System.out.println("❌ WebSocket UI Client mất kết nối");
        isConnected = false;
        listeners.forEach(AuctionWebSocketListener::onDisconnected);
    }

    @Override
    public void onError(Exception ex) {
        System.err.println("⚠️ WebSocket Client error: " + ex.getMessage());
        ex.printStackTrace();
    }

    /**
     * Subscribe tới updates của 1 item
     */
    public void subscribe(int itemId) {
        if (isConnected) {
            JSONObject message = new JSONObject();
            message.put("action", "SUBSCRIBE");
            message.put("itemId", itemId);
            send(message.toString());
            System.out.println(" Gửi SUBSCRIBE itemId: " + itemId);
        } else {
            System.err.println("⚠️ WebSocket chưa kết nối!");
        }
    }

    /**
     * Unsubscribe từ updates của 1 item
     */
    public void unsubscribe(int itemId) {
        if (isConnected) {
            JSONObject message = new JSONObject();
            message.put("action", "UNSUBSCRIBE");
            message.put("itemId", itemId);
            send(message.toString());
            System.out.println(" Gửi UNSUBSCRIBE itemId: " + itemId);
        }
    }

    /**
     * Đăng ký listener để nhận updates
     */
    public void addListener(AuctionWebSocketListener listener) {
        listeners.add(listener);
    }

    /**
     * Bỏ đăng ký listener
     */
    public void removeListener(AuctionWebSocketListener listener) {
        listeners.remove(listener);
    }

    public boolean isConnected() {
        return isConnected;
    }
}
